import { WasmSqliteDriver } from './wasm-sqlite.driver.js';
import { createComponentLogger } from '../utils/component-logger.js';

const log = createComponentLogger('db.service');

export type WorkerFactory = () => Worker;

const defaultWorkerFactory: WorkerFactory = () => new Worker(new URL('./db.worker.ts', import.meta.url), {
    type: 'module',
});

const PERSIST_TIMEOUT_MS = 3000;

/**
 * Resolve `promise`, or reject with a labelled timeout after `ms`. Used to cap
 * boot-critical browser calls that can hang indefinitely on PWA resume.
 */
function withTimeout<T>(promise: Promise<T>, ms: number, label: string): Promise<T> {
    return new Promise<T>((resolve, reject) => {
        const timer = setTimeout(() => reject(new Error(`${label} timed out after ${ms}ms`)), ms);
        promise.then(
            (value) => { clearTimeout(timer); resolve(value); },
            (error) => { clearTimeout(timer); reject(error); },
        );
    });
}

/**
 * How the local-DB bootstrap ended. Story 266: `markBootstrapComplete()` used
 * to run in a `finally`, so a bootstrap that DIED looked identical to one that
 * worked — and story 198's "a missing table is transient until bootstrap ends"
 * contract flipped to "a missing table is a real defect", pushing raw
 * `no such table: settings` into `window.unhandledrejection` (2026-07-22
 * 01:15). Waiters are still released on failure — nobody may hang on a dead
 * bootstrap — but they can now tell the two apart.
 */
export type LocalDbBootstrapStatus = 'pending' | 'succeeded' | 'failed';

/**
 * The local replica is not there and re-reading it cannot change that. Raised
 * instead of letting a raw SQLite `no such table: X` escape when the bootstrap
 * itself failed: recoverable/retryable framing plus the recovery, with the
 * underlying failure kept verbatim (fail-loud, just not cryptic). Story 266.
 */
export class LocalDbUnavailableError extends Error {
    constructor(cause: unknown) {
        const detail = cause instanceof Error ? cause.message : String(cause);
        super(
            'Local database unavailable: its bootstrap failed this session, so reads from the local '
            + 'replica cannot succeed. Retry, or wipe local data and reload to re-download the '
            + `snapshot. Underlying failure: ${detail}`,
            { cause },
        );
        this.name = 'LocalDbUnavailableError';
    }
}

export class DbService {
    private static instance: DbService | null = null;

    private worker: Worker | null = null;
    private driverInstance: WasmSqliteDriver | null = null;
    private bootstrapState: LocalDbBootstrapStatus = 'pending';
    private instanceRevoked = false;
    private bootstrapWaiters: Array<(status: LocalDbBootstrapStatus) => void> = [];

    constructor(
        private readonly workerFactory: WorkerFactory = defaultWorkerFactory,
        private readonly persistTimeoutMs: number = PERSIST_TIMEOUT_MS,
    ) {}

    static getInstance(): DbService {
        if (!DbService.instance) {
            DbService.instance = new DbService();
        }
        return DbService.instance;
    }

    async init(): Promise<void> {
        if (this.instanceRevoked) {
            throw new Error('This window is no longer the live instance (story 281) — reload to use the local database here.');
        }
        if (this.driverInstance) {
            log.debug('init() — already initialized, skipping');
            return;
        }

        log.debug('init() — creating worker...');
        const worker = this.workerFactory();
        this.worker = worker;
        this.driverInstance = new WasmSqliteDriver(worker);
        log.debug('init() — worker created, driver available');

        if (typeof navigator !== 'undefined' && navigator.storage?.persist) {
            // navigator.storage.persist() has been observed to hang forever on
            // PWA resume (client logs, 2026-05-30). Because boot used to start
            // the router only after DB init resolved, that hang left the route
            // outlet empty — an unrecoverable black screen. It is a best-effort
            // hint, so cap it and carry on rather than letting it stall boot.
            // See design_log #155.
            const persisted = await withTimeout(
                navigator.storage.persist(),
                this.persistTimeoutMs,
                'navigator.storage.persist()',
            ).catch((error) => {
                log.warn('storage.persist() did not settle:', error);
                return null;
            });
            log.debug('storage.persist() =', persisted);
        }
    }

    get driver(): WasmSqliteDriver {
        if (this.instanceRevoked) {
            throw new Error(
                'This window is no longer the live instance (story 281) — another window took the local '
                + 'database. Reload to use it here.',
            );
        }
        if (!this.driverInstance) {
            throw new Error('DbService not initialized. Call init() first.');
        }
        return this.driverInstance;
    }

    /**
     * Story 281 — this document lost the single-instance lock to another window.
     *
     * Terminates the worker (so the OPFS sync-access handle is gone, not merely
     * released) and refuses to hand out a driver again. `releaseConnection`
     * would not do: it is deliberately lazy-reopening for bfcache restores
     * (story 266), so any background poller would pull the file straight back
     * open under the new live window — which is the corrupting condition this
     * story exists to remove.
     *
     * Deliberately NOT a reload. A reload from the lock-abort handler is
     * silently dropped by the browser (observed: the call returns, no navigation
     * happens, and the same call a tick later works), so recovery would rest on
     * a timer guess. This is synchronous and has no timing at all; the blocked
     * screen offers a Reload button, and a user gesture always navigates.
     */
    revokeForInstanceLoss(): void {
        this.instanceRevoked = true;
        this.dispose();
    }

    /** Story 281 — true once another window has taken the local database. */
    get isInstanceRevoked(): boolean {
        return this.instanceRevoked;
    }

    /**
     * True once `initializeLocalDatabase()` has finished its snapshot/schema
     * bootstrap (success or failure). While false, a missing local table is a
     * normal in-flight condition — consumers must treat it as transient, never
     * as grounds for destructive recovery (story 190: a status-pill poll
     * during first boot used to queue a wipe that destroyed the freshly
     * imported snapshot).
     */
    get isBootstrapComplete(): boolean {
        return this.bootstrapState !== 'pending';
    }

    /** Whether bootstrap is still in flight, and if not, how it ended. Story 266. */
    get bootstrapStatus(): LocalDbBootstrapStatus {
        return this.bootstrapState;
    }

    markBootstrapSucceeded(): void {
        this.settleBootstrap('succeeded');
    }

    /**
     * Bootstrap ended without a usable local replica. Waiters are released (so
     * no screen hangs) but learn that retrying a local read is pointless.
     * Story 266.
     */
    markBootstrapFailed(): void {
        this.settleBootstrap('failed');
    }

    private settleBootstrap(status: LocalDbBootstrapStatus): void {
        // First outcome wins: a late mark must not rewrite history (and there is
        // exactly one bootstrap per document, so a second mark is a bug).
        if (this.bootstrapState !== 'pending') return;
        this.bootstrapState = status;
        const waiters = this.bootstrapWaiters;
        this.bootstrapWaiters = [];
        for (const resolve of waiters) resolve(status);
    }

    /**
     * Resolves with how bootstrap ended (immediately if it already has). Story
     * 198: a screen that read the local DB mid-bootstrap and hit a transient
     * missing table awaits this, then retries — instead of rendering the raw
     * `no such table` error and giving up (the story-190 transient contract).
     * Story 266 added the resolved value: on `'failed'` there is nothing to
     * retry against, so the consumer surfaces a recoverable state instead.
     */
    whenBootstrapComplete(): Promise<LocalDbBootstrapStatus> {
        if (this.bootstrapState !== 'pending') return Promise.resolve(this.bootstrapState);
        return new Promise<LocalDbBootstrapStatus>((resolve) => { this.bootstrapWaiters.push(resolve); });
    }

    async exists(): Promise<boolean> {
        log.debug('exists() — checking...');
        const result = await this.driver.request<boolean>('db-exists');
        log.debug('exists() =', result);
        return result;
    }

    /**
     * `expectedGeneration` is the server generation this snapshot brings
     * (from /snapshot/info). The worker adopts an existing on-disk DB instead
     * of importing ONLY when it is already at/past that generation (story 214
     * dual-window race); without it, any existing baseline would be adopted
     * and a refresh could never upgrade the DB.
     *
     * `requireNoPending` (story 359): the worker refuses the import — returning false — when
     * the replica holds queued changes, checked in the same locked slot as the import.
     */
    async loadFromSnapshot(
        buffer: ArrayBuffer,
        expectedGeneration?: number,
        options: { requireNoPending?: boolean; replace?: boolean } = {},
    ): Promise<boolean> {
        log.debug('loadFromSnapshot() — buffer size:', buffer.byteLength, 'expectedGeneration:', expectedGeneration);
        const result = await this.driver.request<{ applied: boolean }>(
            'load-snapshot',
            {
                buffer,
                expectedGeneration: expectedGeneration ?? null,
                requireNoPending: options.requireNoPending === true,
                replace: options.replace === true,
            },
            [buffer],
        );
        log.debug('loadFromSnapshot() — DONE', result);
        return result.applied;
    }

    async initSchema(): Promise<void> {
        log.debug('initSchema() — calling worker...');
        await this.driver.request<void>('schema-init');
        log.debug('initSchema() — DONE');
    }

    /**
     * Drop the worker's OPFS connection so the sync-access handle is free for
     * another document immediately. Story 266: on a fast back/forward the
     * outgoing document's worker kept the handle, and the incoming document's
     * `db-exists` hung out the driver's 30 s timeout behind it (2026-07-22
     * 01:15). Driven from `pagehide`, so it must tolerate never having
     * initialised — a document that halted before `init()` has nothing to
     * release, and a listener that throws there breaks unload.
     *
     * The connection is not "closed for good": `openDatabase()` in the worker
     * reopens lazily on the next request, which is what makes this safe for a
     * bfcache restore (`pagehide` with `persisted: true`).
     */
    releaseConnection(): Promise<void> {
        if (!this.driverInstance) {
            return Promise.resolve();
        }
        log.debug('releaseConnection() — asking worker to drop its OPFS handle');
        return this.driverInstance.request<void>('release-connection');
    }

    async wipe(): Promise<void> {
        log.debug('wipe() — calling worker...');
        await this.driver.request<void>('wipe');
        log.debug('wipe() — DONE');
    }

    dispose(): void {
        this.worker?.terminate();
        this.worker = null;
        this.driverInstance = null;
    }
}
