import { DbService } from './db.service.js';
import { API_URL } from '../config.js';
import { apiError } from '../services/http.js';
import { createComponentLogger } from '../utils/component-logger.js';

const log = createComponentLogger('snapshot');

type SnapshotDbService = Pick<DbService, 'loadFromSnapshot'>;

export interface SnapshotDownloadOptions {
    dbService?: SnapshotDbService;
    fetchImpl?: typeof fetch;
    /**
     * How long the download may go without a byte — before the headers, or between chunks — before
     * it is aborted. Not a cap on the whole transfer: on weak 4G a full snapshot takes longer than
     * any sensible total, and still arrives (story 360, pwa-offline-11).
     */
    stallTimeoutMs?: number;
    /**
     * Refuse the import if the replica holds queued changes (story 359). The worker checks in
     * the same locked slot as the import, so a write arriving mid-download cannot slip between.
     */
    requireNoPending?: boolean;
    /**
     * Replace the replica even when its generation already matches, where the worker would adopt
     * it instead (story 360: "Discard N and pull" is asked to throw that file away).
     */
    replace?: boolean;
    /**
     * Server generation this download is expected to bring (callers that
     * already hit /snapshot/info pass it along). When absent, it is fetched
     * from /snapshot/info here — the worker needs it to distinguish "another
     * window already imported this snapshot" (adopt) from "the on-disk DB is
     * a stale older baseline" (must import).
     */
    expectedGeneration?: number;
}

/**
 * Returns `true` when the snapshot was applied, `false` only when `requireNoPending`
 * refused it (queued changes the import would discard). Throws on any
 * other failure — network, HTTP, invalid payload, worker error — so callers
 * see the real cause instead of a swallowed boolean.
 */
export async function downloadAndLoadSnapshot(options: SnapshotDownloadOptions = {}): Promise<boolean> {
    const {
        dbService = DbService.getInstance(),
        fetchImpl = fetch,
        stallTimeoutMs = 10_000,
    } = options;

    const snapshotUrl = `${API_URL}/api/sync/snapshot`;
    log.debug('Attempting snapshot download from:', snapshotUrl);

    const controller = new AbortController();
    let stall: ReturnType<typeof setTimeout> | undefined;
    const progressed = (): void => {
        clearTimeout(stall);
        stall = setTimeout(() => controller.abort(), stallTimeoutMs);
    };
    progressed();

    try {
        const response = await fetchImpl(snapshotUrl, {
            method: 'GET',
            cache: 'no-store',
            signal: controller.signal,
        });
        progressed();

        log.debug('Response status:', response.status);
        if (response.headers) {
            log.debug('Response headers:', Object.fromEntries(response.headers.entries?.() ?? []));
        }

        if (!response.ok) {
            throw await apiError(response, 'Snapshot fetch failed');
        }

        const buffer = await readBody(response, progressed);
        clearTimeout(stall);
        log.debug('Downloaded buffer size:', buffer.byteLength, 'bytes');
        if (buffer.byteLength === 0) {
            throw new Error('Snapshot fetch returned an empty payload');
        }

        let expectedGeneration = options.expectedGeneration;
        if (expectedGeneration === undefined) {
            try {
                const infoResponse = await fetchImpl(`${API_URL}/api/sync/snapshot/info`, { method: 'GET', cache: 'no-store' });
                if (infoResponse.ok) {
                    const info = await infoResponse.json() as { generation?: number };
                    if (typeof info.generation === 'number') expectedGeneration = info.generation;
                }
            } catch {
                // Best-effort: without it the worker falls back to the legacy
                // adopt-on-any-baseline gate (fine for first-import callers).
            }
        }

        log.debug('Loading snapshot into local DB...');
        const applied = await dbService.loadFromSnapshot(buffer, expectedGeneration, {
            requireNoPending: options.requireNoPending,
            replace: options.replace,
        });
        log.debug(`${applied ? 'Snapshot loaded successfully' : 'Snapshot refused: queued changes present'}`);
        return applied;
    } finally {
        clearTimeout(stall);
    }
}

/** The body, chunk by chunk, reporting each one so the stall timer starts over. */
async function readBody(response: Response, onChunk: () => void): Promise<ArrayBuffer> {
    const reader = response.body?.getReader();
    if (!reader) return response.arrayBuffer();
    const chunks: Uint8Array[] = [];
    let size = 0;
    for (;;) {
        const { done, value } = await reader.read();
        if (done) break;
        chunks.push(value);
        size += value.byteLength;
        onChunk();
    }
    const bytes = new Uint8Array(size);
    let offset = 0;
    for (const chunk of chunks) {
        bytes.set(chunk, offset);
        offset += chunk.byteLength;
    }
    return bytes.buffer;
}
